import{z as l,x as p,o as E,c as T,q as r,j as i,D as A,d as e,s as n,S as o,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"FTP 被动模式","description":"","frontmatter":{"title":"FTP 被动模式","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ftp-passive.md","filePath":"cs/ftp-passive.md","lastUpdated":1791413859000}'),B={name:"cs/ftp-passive.md"};function d(P,a,F,h,c,m){const s=p("Mermaid");return E(),T("div",null,[a[2]||(a[2]=r('<h1 id="ftp-被动模式" tabindex="-1">FTP 被动模式 <a class="header-anchor" href="#ftp-被动模式" aria-label="Permalink to &quot;FTP 被动模式&quot;">​</a></h1><div class="epigraph"><p>控制连接在 21，数据连接另开端口；主动模式让服务器回连客户，NAT 失败；PASV 让客户去连服务器宣告的端口。</p><footer>—— 据 RFC 959 FTP；RFC 2428 IPv6 PASV；RFC 1579 防火墙友好整理</footer></div><p><a href="/cs/dhcp-nat">NAT</a> 改了谁能回连。<a href="/cs/ptp-precision-time">上一课</a> 结束时间。缺口是 <strong>FTP 双连接</strong>与被动模式：为何当代少用但仍能讲清 NAT 与 ALG。本课结束名字、时间与邮件课序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>FTP：PORT 命令告诉服务器客户数据口，服务器向客户发起——客户在 NAT 后无映射则失败。PASV：服务器说「来连我的 (h1,h2,p1,p2)」，客户主动连，NAT 友好。IPv6 用 EPSV。应用层网关改包内地址，脆弱。SFTP（SSH 子系统）与 HTTP 上传用单连接，避开这坑。</p><p><span class="marginnote">被动模式（PASV）的「被动」站在服务器角度：服务器不再主动回连客户，而是开一个数据端口「被动地」等你来连。响应里六个数如 (203,0,113,10,200,35) 是 IP 与端口的字节编码：前四个是 203.0.113.10，后两个 200×256+35=51235 是端口号。</span></p><p>不要把 FTP 当推荐文件协议。</p><p><span class="marginnote">RFC 959。本课对照 NAT，不教匿名镜像运营。</span></p><h3 id="载荷嵌地址与-nat-冲突" tabindex="-1">载荷嵌地址与 NAT 冲突 <a class="header-anchor" href="#载荷嵌地址与-nat-冲突" aria-label="Permalink to &quot;载荷嵌地址与 NAT 冲突&quot;">​</a></h3><p>主动回连失败；PASV 让客户发起。ALG 在加密后失效。当代用单连接协议替代。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画主动 vs 被动谁发起数据 TCP。对照 HTTP 单连接 GET。与负载均衡：数据口随机，防火墙要动态开洞或 ALG。</p>',12)),(E(),i(o,null,{default:A(()=>[n(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CTRL%5B%22%E6%8E%A7%E5%88%B6%2021%22%5D%20--%3E%20ACT%5B%22%E4%B8%BB%E5%8A%A8%3A%20%E6%9C%8D%E5%8A%A1%E5%99%A8%E5%9B%9E%E8%BF%9E%22%5D%0A%20%20CTRL%20--%3E%20PASV%5B%22%E8%A2%AB%E5%8A%A8%3A%20%E5%AE%A2%E6%88%B7%E8%BF%9E%E6%95%B0%E6%8D%AE%E5%8F%A3%22%5D%0A%20%20NAT%5B%22NAT%22%5D%20--%3E%20FAIL%5B%22%E4%B8%BB%E5%8A%A8%E5%B8%B8%E5%A4%B1%E8%B4%A5%22%5D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"PMTUD、TLS（FTPS）让双连接更痛。Cookie 无。多播无。当代对象是理解「载荷里嵌地址」与 NAT 冲突——SIP 同类，点名。",-1)),(E(),i(o,null,{default:A(()=>[n(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20C1%5B%22%E5%AE%A2%E6%88%B7%E8%BF%9E%E6%9C%8D%E5%8A%A1%E5%99%A8%2021%EF%BC%9A%E6%8E%A7%E5%88%B6%E8%BF%9E%E6%8E%A5%22%5D%20--%3E%20CMD%5B%22%E5%AE%A2%E6%88%B7%E5%8F%91%20PASV%22%5D%0A%20%20CMD%20--%3E%20RES%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%E5%93%8D%E5%BA%94%E7%AB%AF%E5%8F%A3%E5%85%AD%E5%85%83%E7%BB%84%22%5D%0A%20%20RES%20--%3E%20CALC%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E7%AE%97%E5%87%BA%E6%95%B0%E6%8D%AE%E7%AB%AF%E5%8F%A3%22%5D%0A%20%20CALC%20--%3E%20DATA%5B%22%E5%AE%A2%E6%88%B7%E4%B8%BB%E5%8A%A8%E8%BF%9E%E8%AF%A5%E6%95%B0%E6%8D%AE%E7%AB%AF%E5%8F%A3%22%5D%0A%20%20DATA%20--%3E%20XFER%5B%22%E4%BC%A0%E6%96%87%E4%BB%B6%EF%BC%8C%E6%8E%A7%E5%88%B6%E8%BF%9E%E6%8E%A5%E5%BE%85%E5%91%BD%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">这张图回答「被动模式一次传输到底谁连谁」：控制连接由客户发起，数据连接仍由客户发起——两次都是客户主动，服务器只负责宣告端口。主动模式则反过来要服务器回连客户，NAT 后的客户没有可供回连的映射，于是失败。</span></p><p>安全：明文 FTP 泄露口令，应淘汰。</p><p><span class="marginnote">ALG 可以想象成翻译官：NAT 只会改信封（IP 头），信纸里嵌的地址要靠 FTP 应用层网关代改。可一旦信纸上了锁（TLS 加密），翻译官读不了也改不了——这就是「把 ALG 当安全边界会在加密后失效」的原因。</span></p><p><span class="marginnote">初学者容易以为 NAT 后 FTP 失败是防火墙拦了 21 端口——实际上控制连接常常是通的，坏在 PORT 命令把客户的内网地址（如 192.168.x.x）写进了载荷，服务器照着去连一个不可路由的地址；地址藏在载荷里，NAT 的头部改写规则看不见它。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 FTP 的每一条命令。BitTorrent 与 DHT 是下一课序第一课。后课默认：被动模式为了 NAT；新协议避免分离数据连接。</p><p>把 ALG 当安全边界会在加密后失效。</p><p>下一课<a href="/cs/bittorrent-dht">BitTorrent 与 DHT</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>控制与数据分离，主动回连破 NAT。</li><li>PASV 让客户发起数据连接。</li><li>单连接协议是更干净的替代。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 959；RFC 1579。</li></ul>',10))])}const C=l(B,[["render",d]]);export{f as __pageData,C as default};
